import type {
  BacktestPayload,
  CalibrationPayload,
  ComponentsPayload,
  CoreData,
  CoveragePayload,
  EventsPayload,
  FeedPayload,
  HouseDetail,
  HousesPayload,
  Manifest,
  ModelDiagnosticsPayload,
  MulticyclePayload,
  MethodsPayload,
  Overview,
  PairingsPayload,
  PairingValidationPayload,
  PatternResultsPayload,
  PollsPayload,
  RegistryPayload,
  OperationsPayload,
  TrendPayload,
} from './types';

const DATA_ROOT = '/data/latest';

async function loadJson<T>(name: string): Promise<T> {
  const response = await fetch(`${DATA_ROOT}/${name}`, { headers: { Accept: 'application/json' } });
  if (!response.ok) throw new Error(`Falha ao carregar ${name}: HTTP ${response.status}`);
  return (await response.json()) as T;
}

function assertRun(value: unknown, name: string): asserts value is { run_id: string } {
  if (!value || typeof value !== 'object' || typeof (value as { run_id?: unknown }).run_id !== 'string') {
    throw new Error(`${name} não segue o contrato: run_id ausente`);
  }
}

function assertCoreShape(data: CoreData): void {
  const replayPayloads = [data.overview, data.houses, data.polls, data.trend, data.methods, data.backtest, data.events, data.pairings, data.feed, data.coverage, data.multicycle, data.calibration, data.components, data.patternResults, data.registry, data.pairingValidation, data.modelDiagnostics];
  replayPayloads.forEach((payload, index) => assertRun(payload, `payload de replay ${index + 1}`));
  assertRun(data.operations, 'operations.json');
  if (!Array.isArray(data.overview.nowcast) || !Array.isArray(data.overview.forecast)) {
    throw new Error('overview.json sem faixas obrigatórias');
  }
  if (!Array.isArray(data.polls.polls) || data.polls.polls.some((poll) => !poll.evidence_id || !poll.article_10)) {
    throw new Error('polls.json sem evidência ou ficha do art. 10');
  }
  if (data.events.renormalized !== false || Math.abs(data.events.identity_sum_winner_plus_mass - 1) > 1e-10) {
    throw new Error('events.json viola a identidade de massa ou renormalizou vencedores');
  }
  if (data.events.unmodeled_mass > data.events.unmodeled_mass_threshold) {
    const numericWinner = data.events.events.some((event) => event.event_type === 'vencer_eleicao' && event.p !== undefined);
    if (data.events.winner_publication_status !== 'indisponivel' || numericWinner) {
      throw new Error('events.json publicou vencedor apesar de massa não modelada acima do limiar');
    }
  }
  const replayRunIds = new Set([data.manifest.run_id, ...replayPayloads.map((payload) => payload.run_id)]);
  if (replayRunIds.size !== 1) throw new Error('run_id divergente entre os contratos do replay');
  // operations.json é o ponteiro operacional mutável de 2026. Seu run_id
  // identifica o último run vivo e não deve ser fundido ao replay histórico.
}

export function assertOperationsShape(operations: OperationsPayload): void {
  assertRun(operations, 'operations.json');
  if (!Array.isArray(operations.live_polls) || !operations.live_coverage) {
    throw new Error('operations.json sem cobertura viva obrigatória');
  }
}

export async function loadCoreData(): Promise<CoreData> {
  const [manifest, overview, houses, polls, trend, methods, backtest, events, pairings, feed, coverage, multicycle, calibration, components, patternResults, registry, pairingValidation, modelDiagnostics, operations] = await Promise.all([
    loadJson<Manifest>('manifest.json'),
    loadJson<Overview>('overview.json'),
    loadJson<HousesPayload>('houses.json'),
    loadJson<PollsPayload>('polls.json'),
    loadJson<TrendPayload>('trend.json'),
    loadJson<MethodsPayload>('methods.json'),
    loadJson<BacktestPayload>('backtest.json'),
    loadJson<EventsPayload>('events.json'),
    loadJson<PairingsPayload>('pairings.json'),
    loadJson<FeedPayload>('feed.json'),
    loadJson<CoveragePayload>('coverage.json'),
    loadJson<MulticyclePayload>('multicycle.json'),
    loadJson<CalibrationPayload>('calibration.json'),
    loadJson<ComponentsPayload>('components.json'),
    loadJson<PatternResultsPayload>('pattern_results.json'),
    loadJson<RegistryPayload>('registry.json'),
    loadJson<PairingValidationPayload>('pairing_validation.json'),
    loadJson<ModelDiagnosticsPayload>('model_diagnostics.json'),
    loadJson<OperationsPayload>('operations.json'),
  ]);
  const data = { manifest, overview, houses, polls, trend, methods, backtest, events, pairings, feed, coverage, multicycle, calibration, components, patternResults, registry, pairingValidation, modelDiagnostics, operations };
  assertCoreShape(data);
  return data;
}

export async function loadOperations(): Promise<OperationsPayload> {
  const operations = await loadJson<OperationsPayload>('operations.json');
  assertOperationsShape(operations);
  return operations;
}

export async function loadHouse(id: string, expectedRunId: string): Promise<HouseDetail> {
  const detail = await loadJson<HouseDetail>(`houses/${encodeURIComponent(id)}.json`);
  assertRun(detail, `houses/${id}.json`);
  if (detail.run_id !== expectedRunId) throw new Error('run_id divergente na ficha do instituto');
  return detail;
}
