<script lang="ts">
  import { candidateMedia } from '../lib/candidateMedia';
  import { formatDate, formatPublishedNumber } from '../lib/format';
  import type { LivePoll } from '../lib/types';

  export let livePolls: LivePoll[];
  export let runId: string;

  type Period = '7' | '30' | 'campaign';
  type ChartCandidate = { id: string; label: string; color: string };
  type ChartPoint = { poll: LivePoll; value: number; evidenceId: string };

  const colors = ['#1f65d6', '#5b6b82', '#7c5cc4', '#14806b', '#c1652c', '#2f7eaa'];
  const periods: Array<{ id: Period; label: string }> = [
    { id: '7', label: '7D' },
    { id: '30', label: '30D' },
    { id: 'campaign', label: 'Campanha' },
  ];
  let period: Period = '30';
  let visibleIds = new Set<string>();

  $: latest = livePolls[0];
  $: chartCandidates = (latest?.values ?? []).slice(0, 6).map((value, index): ChartCandidate => ({
    id: value.candidate_id,
    label: candidateMedia(value.candidate_id, value.label).displayName,
    color: colors[index % colors.length],
  }));
  $: tableCandidates = (latest?.values ?? []).map((value, index): ChartCandidate => ({
    id: value.candidate_id,
    label: candidateMedia(value.candidate_id, value.label).displayName,
    color: colors[index % colors.length],
  }));
  $: omittedCount = Math.max(0, tableCandidates.length - chartCandidates.length);
  $: if (visibleIds.size === 0 && chartCandidates.length) visibleIds = new Set(chartCandidates.map((candidate) => candidate.id));
  $: latestTime = latest ? new Date(`${latest.published_at}T12:00:00`).getTime() : 0;
  $: filteredPolls = [...livePolls]
    .filter((poll) => period === 'campaign' || (latestTime - new Date(`${poll.published_at}T12:00:00`).getTime()) / 86_400_000 <= Number(period))
    .sort((a, b) => a.published_at.localeCompare(b.published_at));
  $: maximumValue = Math.max(0, ...filteredPolls.flatMap((poll) => poll.values.map((value) => value.pct)));
  $: yMax = Math.max(40, Math.ceil(maximumValue / 10) * 10);
  $: yTicks = Array.from({ length: 5 }, (_, index) => (yMax / 4) * index);
  $: measurementLabel = filteredPolls.length === 1 ? '1 medição publicada' : `${filteredPolls.length} medições publicadas`;

  function toggleCandidate(id: string): void {
    const next = new Set(visibleIds);
    if (next.has(id) && next.size > 1) next.delete(id);
    else next.add(id);
    visibleIds = next;
  }

  function seriesFor(candidateId: string): ChartPoint[] {
    return filteredPolls.flatMap((poll) => {
      const value = poll.values.find((item) => item.candidate_id === candidateId);
      return value ? [{ poll, value: value.pct, evidenceId: value.evidence_id }] : [];
    });
  }

  function xForPoll(poll: LivePoll): number {
    const index = filteredPolls.findIndex((candidate) => candidate.registration_no === poll.registration_no);
    if (filteredPolls.length <= 1 || index < 0) return 380;
    return 112 + (index * 536) / (filteredPolls.length - 1);
  }

  function yFor(value: number): number {
    return 272 - (Math.min(yMax, Math.max(0, value)) / yMax) * 216;
  }

  function handleChartKey(event: KeyboardEvent): void {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    event.preventDefault();
    (event.currentTarget as HTMLElement).scrollBy({
      left: event.key === 'ArrowRight' ? 120 : -120,
      behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',
    });
  }
</script>

<section class="live-chart-card" aria-labelledby="live-chart-title">
  <header class="section-title-row">
    <div>
      <p class="mini-label">Pesquisas no tempo</p>
      <h2 id="live-chart-title">{measurementLabel}</h2>
      <p>Os marcadores mostram valores publicados por casa e data. Casas diferentes não são conectadas como tendência.</p>
    </div>
    <div class="period-tabs" aria-label="Período do gráfico">
      {#each periods as item}
        <button type="button" class:active={period === item.id} aria-pressed={period === item.id} onclick={() => period = item.id}>{item.label}</button>
      {/each}
    </div>
  </header>

  <div class="chart-legend" role="group" aria-label="Séries exibidas">
    {#each chartCandidates as candidate}
      <button
        type="button"
        class:muted={!visibleIds.has(candidate.id)}
        aria-pressed={visibleIds.has(candidate.id)}
        style={`--series-color:${candidate.color}`}
        onclick={() => toggleCandidate(candidate.id)}
      ><span aria-hidden="true"></span>{candidate.label}</button>
    {/each}
  </div>
  {#if omittedCount}<p class="chart-scope-note">O gráfico destaca as 6 candidaturas com maior percentual na publicação mais recente. As {omittedCount} demais continuam disponíveis na tabela abaixo.</p>{/if}

  <p class="chart-swipe-hint">Deslize horizontalmente para ler datas e rótulos do gráfico.</p>
  <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
  <!-- svelte-ignore a11y_no_noninteractive_element_interactions -->
  <div class="live-chart-wrap" tabindex="0" role="region" aria-label="Gráfico rolável de pesquisas publicadas" onkeydown={handleChartKey}>
    {#if filteredPolls.length}
      <svg viewBox="0 0 760 340" role="img" aria-labelledby="chart-svg-title chart-svg-desc">
        <title id="chart-svg-title">Percentuais publicados nas pesquisas nacionais de 2026</title>
        <desc id="chart-svg-desc">{filteredPolls.length} pesquisas nacionais validadas são exibidas como marcadores independentes. Nenhuma tendência foi estimada.</desc>
        {#each yTicks as tick}
          <line class="chart-gridline" x1="82" x2="680" y1={yFor(tick)} y2={yFor(tick)} />
          <text class="chart-axis-label" x="68" y={yFor(tick) + 4} text-anchor="end">{tick}%</text>
        {/each}
        <line class="chart-axis" x1="82" x2="680" y1="272" y2="272" />

        {#each chartCandidates.filter((candidate) => visibleIds.has(candidate.id)) as candidate}
          {@const points = seriesFor(candidate.id)}
          {#each points as point}
            <circle
              class="series-point-ring"
              cx={xForPoll(point.poll)}
              cy={yFor(point.value)}
              r="7"
              stroke={candidate.color}
            />
            <circle
              class="series-point"
              cx={xForPoll(point.poll)}
              cy={yFor(point.value)}
              r="4"
              fill={candidate.color}
              data-value={point.value}
              data-kind="Publicado"
              data-run-id={runId}
              data-evidence={point.evidenceId}
            />
          {/each}
        {/each}

        {#each filteredPolls as poll}
          <line class="date-tick" x1={xForPoll(poll)} x2={xForPoll(poll)} y1="272" y2="278" />
          <text class="chart-date" x={xForPoll(poll)} y="300" text-anchor="middle">{formatDate(poll.published_at)}</text>
          <text class="chart-house" x={xForPoll(poll)} y="320" text-anchor="middle">{poll.institute}</text>
        {/each}
      </svg>
    {:else}
      <p class="chart-no-data">Nenhuma pesquisa dentro deste período.</p>
    {/if}
  </div>

  <div class="insufficient-note" role="note">
    <span aria-hidden="true">i</span>
    <p><strong>{filteredPolls.length < 3 ? 'Dados insuficientes para inferir movimento.' : 'Marcadores não equivalem a uma tendência.'}</strong> Diferenças entre casas podem refletir campo, método e amostra; o gráfico não as interpola.</p>
  </div>

  <details class="chart-data-table">
    <summary>Ver valores em tabela</summary>
    <div>
      <table>
        <thead><tr><th>Candidatura</th>{#each filteredPolls as poll}<th class="num">{poll.institute}<small>{formatDate(poll.published_at)}</small></th>{/each}</tr></thead>
        <tbody>
          {#each tableCandidates as candidate}
            <tr><th scope="row">{candidate.label}</th>{#each filteredPolls as poll}{@const value = poll.values.find((item) => item.candidate_id === candidate.id)?.pct}<td class="num">{value === undefined ? '—' : `${formatPublishedNumber(value)}%`}</td>{/each}</tr>
          {/each}
        </tbody>
      </table>
    </div>
  </details>
</section>
