<script lang="ts">
  import { onMount } from 'svelte';
  import LiveFooter from './components/LiveFooter.svelte';
  import { loadCoreData, loadOperations } from './lib/data';
  import { formatDateTime } from './lib/format';
  import type { CoreData, OperationsPayload } from './lib/types';
  import Lab from './pages/Lab.svelte';
  import LiveHome from './pages/LiveHome.svelte';
  import LiveInstitutes from './pages/LiveInstitutes.svelte';
  import LiveMethods from './pages/LiveMethods.svelte';
  import LivePolls from './pages/LivePolls.svelte';

  let data: CoreData | null = null;
  let operations: OperationsPayload | null = null;
  let replayLoading = false;
  let error = '';
  let replayError = '';
  let path = window.location.pathname;
  let search = window.location.search;
  let menuOpen = false;

  $: houseId = path.startsWith('/institutos/') ? decodeURIComponent(path.split('/')[2] ?? '') : '';
  $: initialHouse = new URLSearchParams(search).get('casa') ?? '';
  $: needsReplay = path === '/laboratorio';
  $: if (operations && needsReplay && !data && !replayLoading && !replayError) {
    void fetchReplay();
  }
  $: document.title = pageTitle(path);

  async function fetchReplay(): Promise<void> {
    replayLoading = true;
    replayError = '';
    try {
      data = await loadCoreData();
    } catch (reason) {
      replayError = reason instanceof Error ? reason.message : 'Falha ao carregar o replay histórico.';
    } finally {
      replayLoading = false;
    }
  }

  function pageTitle(currentPath: string): string {
    if (currentPath === '/') return 'Visão geral · Radar Eleitoral 2026';
    if (currentPath === '/institutos') return 'Institutos · Radar Eleitoral 2026';
    if (currentPath.startsWith('/institutos/')) return 'Ficha do instituto · Radar Eleitoral 2026';
    if (currentPath === '/pesquisas') return 'Pesquisas · Radar Eleitoral 2026';
    if (currentPath === '/metodologia') return 'Metodologia · Radar Eleitoral 2026';
    if (currentPath === '/laboratorio') return 'Laboratório · Radar Eleitoral 2026';
    return 'Radar Eleitoral 2026';
  }

  function syncLocation(): void {
    path = window.location.pathname;
    search = window.location.search;
  }

  function scrollToHash(hash: string): void {
    if (!hash) return;
    const id = decodeURIComponent(hash.slice(1));
    requestAnimationFrame(() => {
      const target = document.getElementById(id);
      if (!target) return;
      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      target.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
    });
  }

  function navigate(url: URL): void {
    window.history.pushState({}, '', `${url.pathname}${url.search}${url.hash}`);
    menuOpen = false;
    syncLocation();
    if (url.hash) {
      scrollToHash(url.hash);
    } else {
      window.scrollTo({ top: 0, behavior: 'auto' });
    }
  }

  onMount(() => {
    let operationsTimer: ReturnType<typeof setInterval> | undefined;
    const clickHandler = (event: MouseEvent) => {
      const target = event.target as Element | null;
      const anchor = target?.closest<HTMLAnchorElement>('a[data-route]');
      if (!anchor || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      const url = new URL(anchor.href, window.location.href);
      if (url.origin !== window.location.origin) return;
      event.preventDefault();
      navigate(url);
    };
    const popHandler = () => syncLocation();
    const keyHandler = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && menuOpen) menuOpen = false;
    };
    const outsideHandler = (event: MouseEvent) => {
      if (!menuOpen) return;
      const target = event.target as Element | null;
      if (!target?.closest('.site-header')) menuOpen = false;
    };
    document.addEventListener('click', clickHandler);
    document.addEventListener('click', outsideHandler);
    document.addEventListener('keydown', keyHandler);
    window.addEventListener('popstate', popHandler);

    void loadOperations()
      .then((loaded) => {
        operations = loaded;
        scrollToHash(window.location.hash);
        operationsTimer = setInterval(() => {
          void loadOperations().then((loadedOperations) => {
            operations = loadedOperations;
          }).catch(() => undefined);
        }, 30_000);
      })
      .catch((reason) => {
        error = reason instanceof Error ? reason.message : 'Falha ao carregar os contratos do dashboard.';
      });

    return () => {
      document.removeEventListener('click', clickHandler);
      document.removeEventListener('click', outsideHandler);
      document.removeEventListener('keydown', keyHandler);
      window.removeEventListener('popstate', popHandler);
      if (operationsTimer) clearInterval(operationsTimer);
    };
  });
</script>

<a class="skip-link" href="#main-content">Pular para o conteúdo</a>

<header class="site-header">
  <div class="site-header-inner">
    <a class="site-brand" href="/" data-route aria-label="Radar Eleitoral 2026 — ir para a Visão geral">
      <span class="site-brand-mark" aria-hidden="true">26</span>
      <span><strong>Radar Eleitoral</strong><small>dados verificados · 2026</small></span>
    </a>
    <button class="menu-button" type="button" aria-expanded={menuOpen} aria-controls="site-navigation" aria-label={menuOpen ? 'Fechar menu' : 'Abrir menu'} onclick={() => menuOpen = !menuOpen}>
      <span></span><span></span><span></span>
    </button>
    <nav id="site-navigation" class:open={menuOpen} class="site-navigation" aria-label="Navegação principal">
      <a class:active={path === '/'} aria-current={path === '/' ? 'page' : undefined} href="/" data-route>Visão geral</a>
      <a class:active={path === '/pesquisas'} aria-current={path === '/pesquisas' ? 'page' : undefined} href="/pesquisas" data-route>Pesquisas</a>
      <a class:active={path.startsWith('/institutos')} aria-current={path.startsWith('/institutos') ? 'page' : undefined} href="/institutos" data-route>Institutos</a>
      <a class:active={path === '/laboratorio'} aria-current={path === '/laboratorio' ? 'page' : undefined} href="/laboratorio" data-route>Laboratório</a>
      <a class:active={path === '/metodologia'} aria-current={path === '/metodologia' ? 'page' : undefined} href="/metodologia" data-route>Metodologia</a>
    </nav>
    <div class="site-header-actions">
      {#if operations?.last_source_check}<span class="header-updated"><span aria-hidden="true"></span>Atualizado {formatDateTime(operations.last_source_check)}</span>{/if}
      <a class="header-data-link" href="/data/latest/operations.json" download>Dados</a>
    </div>
  </div>
</header>

<main id="main-content" tabindex="-1">
  {#if error}
    <section class="load-state error-state" role="alert">
      <p class="eyebrow">Falha de contrato</p>
      <h1>O dashboard não pôde abrir os dados.</h1>
      <p>{error}</p>
      <p>Execute novamente o pipeline e valide os JSON Schemas antes do build.</p>
    </section>
  {:else if !operations}
    <section class="load-state" aria-live="polite"><span class="loading-mark" aria-hidden="true"></span><p>Carregando execução auditável…</p></section>
  {:else if path === '/'}
    <LiveHome {operations} />
  {:else if path === '/institutos'}
    <LiveInstitutes {operations} />
  {:else if houseId}
    <section class="load-state"><p class="eyebrow">Institutos 2026</p><h1>Ficha individual ainda não publicada</h1><p>Com apenas duas casas na janela viva, o painel não publica comparação ou desempenho individual.</p><a href="/institutos" data-route>Ver institutos cobertos</a></section>
  {:else if path === '/pesquisas'}
    <LivePolls {operations} {initialHouse} />
  {:else if path === '/metodologia'}
    <LiveMethods {operations} />
  {:else if path === '/laboratorio'}
    {#if replayError}
      <section class="load-state error-state" role="alert"><h1>Laboratório indisponível</h1><p>{replayError}</p></section>
    {:else if data}
      <Lab {data} />
    {:else}
      <section class="load-state" aria-live="polite"><p>Carregando replay histórico…</p></section>
    {/if}
  {:else}
    <section class="load-state"><p class="eyebrow">404</p><h1>Página não encontrada</h1><a href="/" data-route>Voltar à Visão geral</a></section>
  {/if}
</main>

{#if operations}<LiveFooter {operations} />{/if}
